#include "runtime.hpp"
#include "cost_workload.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <memory>
using namespace pas;using namespace pas::current_rails;using J=nlohmann::json;
std::vector<std::uint8_t> raster(int head,int x,std::string_view change){using cost_workload::box;std::vector<std::uint8_t> p(1280*720*3,0);box(p,20,20,26,42,{255,255,255});box(p,34,20,40,42,{255,255,255});for(int d=0;d<6;++d)box(p,1020+d*24,20,1032+d*24,40,{255,255,255});box(p,115,499,1165,502,{255,255,255});if(change!="absence"){auto color=change=="effect"?std::array<std::uint8_t,3>{230,190,70}:std::array<std::uint8_t,3>{40,190,255};box(p,x-50,head-100,x+51,head+1,color);box(p,x-50,head-100,x-48,head+1,{255,255,255});box(p,x+49,head-100,x+51,head+1,{255,255,255});}return p;}
J run(int head,bool candidate,std::string_view control){FakeClock clock;auto rt=std::make_unique<Runtime>(clock);J frames=J::array(),events=J::array();rt->event_output=[&](J e){auto type=e.at("event").get<std::string>();if(type=="own_accepted_plan"||type=="plan_cancelled"||type=="plan_cancellation")events.push_back(e);};rt->receipt_output=[&](const auto&e){if(e.release){events.push_back({{"event","release_receipt"},{"requested",e.report.requested_ids}});}else{events.push_back({{"event","receipt"},{"phase",int(e.issued.phase)},{"frame",e.issued.source_frame_sequence},{"time",e.receipt.injection_start_ns},{"scheduled",e.issued.scheduled_ns},{"success",e.receipt.success}});}};bool safe=true;for(int k=0;k<12;++k){Frame f;f.sequence=k+1;f.epoch=f.generation=f.geometry_version=1;f.width=1280;f.height=720;f.stride=3840;f.source_rotation=1;f.capture_complete_ns=f.pixels_ready_ns=1'000'000'000LL+(k+1)*20'000'000LL;int y=head+(k-4)*16;std::string_view change="none";int x=400;if(k>=5){if(control=="body_hold")y=head;else if(control=="leave")x=700;else if(control=="absence"||control=="effect")change=control;}f.rgb=raster(y,x,change);clock.set(f.capture_complete_ns);bool ok=rt->dispatch(f,candidate);J supports=J::array();for(size_t j=0;j<rt->last.count;++j){const auto&s=rt->last.support[j];supports.push_back({{"note",s.note},{"terminal",s.terminal},{"body",s.body},{"active",s.active},{"tail",s.tail},{"accepted",s.accepted},{"reason",s.reason}});}J raw=J::array();const auto&b=rt->observer.candidate_batch();for(const auto&c:b.candidates)raw.push_back({{"kind",int(c.note.kind)},{"front",{c.note.center.x,c.note.center.y}},{"tail",c.note.tail?J::array({c.note.tail->x,c.note.tail->y}):J(nullptr)},{"front_measure",hold_front::encode(hold_front::measure(f,b.context,c))}});frames.push_back({{"frame",k+1},{"head",y},{"safe",ok},{"raw",raw},{"support",supports},{"down",rt->backend.downs},{"move",rt->backend.moves},{"up",rt->backend.ups},{"active",rt->backend.active_count()}});if(!ok){safe=false;break;}}bool released=rt->finish();return {{"head_at_frame5",head},{"mode",candidate?"B":"A"},{"control",control},{"safe",safe},{"released",released},{"down",rt->backend.downs},{"move",rt->backend.moves},{"up",rt->backend.ups},{"frames",frames},{"events",events}};}
int main(int argc,char**argv){if(argc!=2||std::filesystem::exists(argv[1]))return 2;J runs=J::array();for(int head=490;head<=510;++head)for(bool b:{false,true})runs.push_back(run(head,b,"approach_body_tail"));for(const auto control:{"body_hold","leave","absence","effect"})for(bool b:{false,true})runs.push_back(run(503,b,control));J report={{"schema","pas.predeclared-workload-sweep.v1"},{"head_min",490},{"head_max",510},{"attempts_per_run",12},{"cadence_ms",20},{"runs",runs},{"cost_qualification",false},{"physical_gold",0}};std::ofstream f(argv[1]);f<<report.dump(2)<<'\n';}
